def load_payload():
    raw = base64.b64decode(PAYLOAD_B64)
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        manifest = json.loads(zf.read('manifest.json').decode('utf-8'))
        data = {name: zf.read(name) for name in zf.namelist() if name != 'manifest.json'}
    return manifest, data


def sha256_bytes(b):
    return hashlib.sha256(b).hexdigest()


def sha256_file(path, chunk=1 << 20):
    h = hashlib.sha256()
    with open(path, 'rb') as fh:
        for piece in iter(lambda: fh.read(chunk), b''):
            h.update(piece)
    return h.hexdigest()


def find_game_root(guess):
    '''Aceita a raiz do port (com game/ e conf/) ou a própria pasta game/.'''
    guess = os.path.abspath(os.path.expanduser(os.path.expandvars(guess)))
    for game in (os.path.join(guess, 'game'), guess):
        if (os.path.isfile(os.path.join(game, 'sys', 'fst.bin'))
                and os.path.isdir(os.path.join(game, 'files'))):
            return game
    return None


def state_of(path, entry):
    if not os.path.isfile(path):
        return 'missing'
    digest = sha256_file(path)
    if digest == entry['sha256']:
        return 'patched'
    if digest == entry['sha256_clean']:
        return 'clean'
    return 'unknown'


STATE_LABEL = {
    'clean': 'limpo (tradução não aplicada)',
    'patched': 'JÁ TRADUZIDO',
    'unknown': 'modificado (não é o original nem a tradução)',
    'missing': 'ausente',
}


def backup_path(game_root, target):
    return os.path.join(game_root, '_backup_traducao', target.replace('/', os.sep))


def check_env_txt(port_root):
    env = os.path.join(port_root, 'conf', 'env.txt')
    if not os.path.isfile(env):
        print('[?] conf/env.txt não encontrado; o idioma do port não foi verificado.')
        return
    lang = None
    with open(env, 'r', encoding='utf-8', errors='replace') as fh:
        for line in fh:
            line = line.strip()
            if line.upper().startswith('PETARI_LANGUAGE='):
                lang = line.split('=', 1)[1].strip()
                break
    if lang is None:
        print('[?] PETARI_LANGUAGE não definido em conf/env.txt.')
    elif lang.lower() in ('english', 'spanish'):
        print('[OK] PETARI_LANGUAGE=%s — esse slot contém o texto em PT-BR.' % lang)
    elif lang.lower() == 'french':
        print('[!] PETARI_LANGUAGE=french — o slot francês NÃO recebeu a tradução!')
        print('     Edite conf/env.txt e mude para english (ou spanish) para jogar em PT-BR.')
    else:
        print('[?] PETARI_LANGUAGE=%s — valor desconhecido.' % lang)


def do_check(game_root, manifest, data, apply=False, restore=False):
    targets = [(e['target'], os.path.join(game_root, e['target'].replace('/', os.sep)))
               for e in manifest['entries']]
    if restore:
        print('== Restaurando originais ==')
        restored = skipped = problems = 0
        for target, path in targets:
            entry = next(e for e in manifest['entries'] if e['target'] == target)
            bak = backup_path(game_root, target)
            if os.path.isfile(bak):
                shutil.copyfile(bak, path)
                restored += 1
            elif os.path.isfile(path) and sha256_file(path) == entry['sha256_clean']:
                skipped += 1
            elif os.path.isfile(path) and sha256_file(path) == entry['sha256']:
                print('[X] %s está traduzido e sem backup; impossível reverter' % target)
                problems += 1
                continue
            else:
                print('[X] %s: estado desconhecido, sem backup; não toquei' % target)
                problems += 1
                continue
            digest = sha256_file(path)
            if digest == entry['sha256_clean']:
                print('[OK] restaurado  %s' % target)
            else:
                print('[X] %s: checksum após restaurar não confere!' % target)
                problems += 1
        print('Restaurados: %d | já estavam originais: %d | problemas: %d'
              % (restored, skipped, problems))
        return 1 if problems else 0

    print('== Estado atual ==')
    for target, path in targets:
        entry = next(e for e in manifest['entries'] if e['target'] == target)
        print('  [%s] %s' % (STATE_LABEL[state_of(path, entry)][:1], target))
        print('        %s' % STATE_LABEL[state_of(path, entry)])

    if not apply:
        return 0

    print('== Aplicando a tradução ==')
    applied = skipped = problems = 0
    for target, path in targets:
        entry = next(e for e in manifest['entries'] if e['target'] == target)
        state = state_of(path, entry)
        payload = data['patched/' + target]
        if state == 'patched':
            print('[OK] já traduzido:  %s' % target)
            skipped += 1
            continue
        if state in ('clean', 'unknown', 'missing'):
            if state != 'missing':
                bak = backup_path(game_root, target)
                if os.path.isfile(bak):
                    print('[i] backup já existia: _backup_traducao/%s' % target)
                else:
                    os.makedirs(os.path.dirname(bak), exist_ok=True)
                    shutil.copyfile(path, bak)
                    print('[i] original salvo em _backup_traducao/%s' % target)
            if state == 'unknown':
                print('[!] %s não estava no estado esperado; substituindo mesmo assim' % target)
            os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
            with open(path, 'wb') as fh:
                fh.write(payload)
            if sha256_file(path) != entry['sha256']:
                print('[X] ERRO: %s não confere após escrever! (restaure do backup)' % target)
                problems += 1
                continue
            print('[OK] aplicado:      %s (%d bytes)' % (target, len(payload)))
            applied += 1
    print('Aplicados: %d | já traduzidos: %d | problemas: %d' % (applied, skipped, problems))
    return 1 if problems else 0


def main(argv):
    print('=' * 62)
    print('  %s' % APP_TITLE)
    print('  Tradução: %s' % TRADUCAO_CREDITO)
    print('  Aplicador v%s — arquivos embutidos, não precisa de ISO' % APP_VERSION)
    print('=' * 62)

    restore = '--restore' in argv
    check_only = '--check' in argv
    args = [a for a in argv[1:] if not a.startswith('--')]
    guess = args[0] if args else ''
    if not guess:
        guess = input('Pasta do port (ex.: D:\\ports\\smgalaxy): ').strip()
    guess = guess.strip('"').strip("'")
    if not guess:
        print('[X] Nenhuma pasta informada.')
        return 2

    game_root = find_game_root(guess)
    if game_root is None:
        print('[X] "%s" não parece um port do Super Mario Galaxy.' % guess)
        print('    Informe a pasta que contém game/sys/fst.bin')
        print('    (a raiz do port, ex.: D:\\ports\\smgalaxy, ou a própria game/).')
        return 2
    port_root = os.path.dirname(game_root) or game_root
    print('[OK] Port encontrado: %s' % game_root)

    manifest, data = load_payload()
    print('[OK] Tradução embutida: %d arquivos (%s)' % (
        len(manifest['entries']), manifest.get('traducao', TRADUCAO_CREDITO)))

    if not check_only and not restore:
        check_env_txt(port_root)

    code = do_check(game_root, manifest, data, apply=not check_only and not restore,
                    restore=restore)
    if restore:
        print('\nOriginais restaurados. O port voltou ao estado sem tradução.')
    elif check_only:
        print('\n(--check: nada foi escrito)')
    else:
        print('\nPronto! Se o port estava com PETARI_LANGUAGE=english ou spanish,')
        print('ele já inicia em português. Bom jogo! o/')
    return code


if __name__ == '__main__':
    sys.exit(main(sys.argv))
